ABLATION_HEADING_NEW = r"\subsection{Controlled ablation of the resonance-aware decomposition and the RBF-FD physics loss}" + "\n" + r"\label{app:ablation}"


def main() -> None:
    text = TEX.read_text(encoding="utf-8")
    missing = [(old, new) for old, new in PAIRS if text.count(old) != 1]
    if missing:
        for old, _ in missing:
            print(f"MISSING/AMBIGUOUS ({text.count(old)}): {old[:90]}")
        raise SystemExit(1)
    for old, new in PAIRS:
        text = text.replace(old, new)

    # Move the ablation subsection from Results to Appendix B.
    start_marker = r"\subsection{Contribution of the resonance-aware decomposition and the RBF-FD physics loss}"
    end_marker = r"\subsection{Ellipsoidal response envelopes and resonance ranges}"
    start = text.index(start_marker)
    end = text.index(end_marker)
    block = text[start:end]
    if "Supplementary diagnostics" in block:
        block = block.rsplit("Supplementary diagnostics", 1)[0].rstrip() + "\n\n"
    block = block.replace(start_marker, ABLATION_HEADING_NEW, 1)
    text = text[:start] + NEW_SUBSECTION.lstrip() + "\n\n" + text[end:]
    text = text.replace(r"\bibliographystyle{elsarticle-num}",
                        block + "\n" + r"\bibliographystyle{elsarticle-num}", 1)

    # Insert the two supplementary tables after their anchor tables.
    def insert_after_table(text: str, anchor_label: str, new_table: str) -> str:
        pattern = re.compile(
            r"(\\label\{" + re.escape(anchor_label) + r"\}.*?\\end\{table\})",
            re.DOTALL,
        )
        match = pattern.search(text)
        if not match:
            raise RuntimeError(f"anchor table not found: {anchor_label}")
        return text[: match.end()] + "\n" + new_table + text[match.end() :]

    text = insert_after_table(text, "tab:results_convergence", CONVERGENCE_DIAGNOSTICS_TABLE)
    text = insert_after_table(text, "tab:results_extremum_backsubstitution", LARGE_SAMPLE_TABLE)

    TEX.write_text(text, encoding="utf-8")
    print("Results rewrite applied.")


if __name__ == "__main__":
    main()
